import zlib, sys, os
G = sys.argv[1]
def obj(sha):
    d = zlib.decompress(open(os.path.join(G, 'objects', sha[:2], sha[2:]), 'rb').read())
    h, _, b = d.partition(b'\0'); return h.split()[0].decode(), b
def tree(sha, pre=''):
    _, b = obj(sha); i = 0; out = {}
    while i < len(b):
        sp = b.index(b' ', i); nul = b.index(b'\0', sp)
        mode = b[i:sp].decode(); name = b[sp+1:nul].decode(); s = b[nul+1:nul+21].hex(); i = nul+21
        if mode == '40000': out.update(tree(s, pre+name+'/'))
        else: out[pre+name] = s
    return out
def commit_tree(sha):
    _, b = obj(sha); return b.split(b'\n')[0].split()[1].decode()
c = sys.argv[2]
t = tree(commit_tree(c))
if len(sys.argv) > 3:
    sys.stdout.write(obj(t[sys.argv[3]])[1].decode())
else:
    for k, v in sorted(t.items()): print(v, k)
